329	// parseCursorHookType parses a specific hook type from rawHooks into the target slice.
330	// Silently ignores parse errors (leaves target unchanged).
331	func parseCursorHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CursorHookEntry) {
332		if data, ok := rawHooks[hookType]; ok {
333			//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
334			json.Unmarshal(data, target)
335		}
336	}
