338	// marshalCursorHookType marshals a hook type back into rawHooks.
339	// If the slice is empty, removes the key from rawHooks.
340	func marshalCursorHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CursorHookEntry) {
341		if len(entries) == 0 {
342			delete(rawHooks, hookType)
343			return
344		}
345		data, err := jsonutil.MarshalWithNoHTMLEscape(entries)
346		if err != nil {
347			return // Silently ignore marshal errors (shouldn't happen)
348		}
349		rawHooks[hookType] = data
350	}
