		wrappedCommand = strings.TrimSuffix(wrappedCommand, `"`)
		wrappedCommand = strings.TrimSuffix(wrappedCommand, `)`)
		return hasManagedHookPrefix(wrappedCommand, prefixes)
	}
	return false
}

